{
  "findings": [
    {
      "ref": "[D502]",
      "area": "age_gating",
      "claim": "A parent reports that children under 13 can use Roblox if a parent creates a linked account and enables parental controls.",
      "stance": "neutral",
      "quote": "Users ages 5 and older may create an Account, but certain features for the Services must be enabled by a parent or legal guardian through our Parental Controls."
    },
    {
      "ref": "[D502]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with a child unless parental controls are turned off.",
      "stance": "risk",
      "quote": "If you use Roblox Studio, Creator Store, Creator Hub, DevForum, Roblox APIs or other Developer Products, services, or associated software (collectively, “Roblox Creator Platform”), the Creator Terms of Use (“Creator Terms”) also apply to that use."
    },
    {
      "ref": "[D502]",
      "area": "money",
      "claim": "A parent reports that Roblox pushes in-app purchases (Robux) and loot-box-like mechanics that can lead to overspending.",
      "stance": "risk",
      "quote": "Roblox may offer you access to additional benefits or other digital items provided by Roblox through paid subscriptions (“Roblox Subscription”)."
    },
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal data such as email, phone number, and ID, and may share it with third parties for advertising.",
      "stance": "risk",
      "quote": "You may be asked to provide information like an email address, phone number, or a government-issued photo identification to access certain Content or features in Roblox Player."
    },
    {
      "ref": "[D502]",
      "area": "content",
      "claim": "A parent reports that children frequently encounter violent or sexual user-generated content despite age gating.",
      "stance": "risk",
      "quote": "The Services may display UGC created by other Users for use with your avatar, such as clothing, accessories, or other digital items (“User Marketplace Items”)."
    },
    {
      "ref": "[D502]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory fines for violating child privacy laws.",
      "stance": "risk",
      "quote": "Roblox may block, remove, or delete Content in certain regions for legal and regulatory reasons, such as an order or injunction from any court, administrative body, or regulatory authority."
    }
  ]
}
